INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1010984, 121208, 15811, '<td valign="top">Could use a bit more focus and a bit too dark for my taste.  That border doesn''t help much eitehr though -- good concept however.</td>', 'Could use a bit more focus and a bit too dark for my taste.  That border doesn''t help much eitehr though -- good concept however.', '2004-11-15 00:13:02.000000', NULL, 1),
(1011005, 120641, 93, '<td valign="top">Hahaahahahahahaah..<br/>Love it.  Alfred E. Neuman is the best.</td>', 'Hahaahahahahahaah..Love it.  Alfred E. Neuman is the best.', '2004-11-15 00:18:32.000000', NULL, 1),
(1011045, 120698, 25464, '<td valign="top">This is definitely a 10.  Perfect pose, expression, composition.  The light is harsh but appropriate.  My pick for a ribbon.</td>', 'This is definitely a 10.  Perfect pose, expression, composition.  The light is harsh but appropriate.  My pick for a ribbon.', '2004-11-15 00:30:47.000000', NULL, 1),
(1011048, 121006, 25464, '<td valign="top">This is a beautiful portrait.  I don''t know if everyone will relate to the hero connection, but I hope so. 10.</td>', 'This is a beautiful portrait.  I don''t know if everyone will relate to the hero connection, but I hope so. 10.', '2004-11-15 00:32:17.000000', NULL, 1),
(1011050, 121217, 26799, '<td valign="top">I think I recognize the person in this photo. Is her name Amber?</td>', 'I think I recognize the person in this photo. Is her name Amber?', '2004-11-15 00:35:25.000000', NULL, 1),
(1011057, 119712, 24384, '<td valign="top">Ha Ha Ha... awesome!</td>', 'Ha Ha Ha... awesome!', '2004-11-15 00:37:47.000000', NULL, 1),
(1011072, 121416, 24384, '<td valign="top">Very.... Very.. Good</td>', 'Very.... Very.. Good', '2004-11-15 00:42:59.000000', NULL, 1),
(1011078, 121401, 25464, '<td valign="top">This is a great idea, and very nice.  I think; however, it could have been better if it were not cropped so tightly, or angled so that you could make out a piece of the form of the truck.  The flat view of all of the reflection is a bit busy to my eye.</td>', 'This is a great idea, and very nice.  I think; however, it could have been better if it were not cropped so tightly, or angled so that you could make out a piece of the form of the truck.  The flat view of all of the reflection is a bit busy to my eye.', '2004-11-15 00:45:02.000000', NULL, 1),
(1011082, 121181, 25464, '<td valign="top">This is a fun shot.  I might have cropped a bit tighter, but excellent expression and emotion.  Black and white is a great choice for this shot.</td>', 'This is a fun shot.  I might have cropped a bit tighter, but excellent expression and emotion.  Black and white is a great choice for this shot.', '2004-11-15 00:46:19.000000', NULL, 1),
(1011083, 121276, 25464, '<td valign="top">This portrait holds a lot of emotion.  I can''t make the hero connection with the photo and/or title, but I am guessing this is a personal choice (no deduction).  The only distraction I see is the crop.  I think this needed a tighter crop on the top and left which would have made the subjects face less centered.  Still, excellent photo. 8.</td>', 'This portrait holds a lot of emotion.  I can''t make the hero connection with the photo and/or title, but I am guessing this is a personal choice (no deduction).  The only distraction I see is the crop.  I think this needed a tighter crop on the top and left which would have made the subjects face less centered.  Still, excellent photo. 8.', '2004-11-15 00:46:48.000000', NULL, 1),
(1011086, 120899, 25464, '<td valign="top">Excellent composition and expression.  Different. 8.</td>', 'Excellent composition and expression.  Different. 8.', '2004-11-15 00:48:17.000000', NULL, 1),
(1011091, 120676, 24384, '<td valign="top">Excellent job!</td>', 'Excellent job!', '2004-11-15 00:49:21.000000', NULL, 1),
(1011097, 121331, 25464, '<td valign="top">This is a beautiful portrait.  I think this would have done well in the Calendar challenge. Great color and DOF.  I don''t think it actually portrays a hero or what a hero means to you.</td>', 'This is a beautiful portrait.  I think this would have done well in the Calendar challenge. Great color and DOF.  I don''t think it actually portrays a hero or what a hero means to you.', '2004-11-15 00:50:52.000000', NULL, 1),
(1011114, 120311, 16241, '<td valign="top">hey thats very cool, i like it</td>', 'hey thats very cool, i like it', '2004-11-15 00:57:21.000000', NULL, 1),
(1011119, 119712, 16241, '<td valign="top">that is so funny, can just imagine who this is!<br/></td>', 'that is so funny, can just imagine who this is!', '2004-11-15 01:00:09.000000', NULL, 1),
(1011131, 121416, 24976, '<td valign="top">i would give you an 11 if i could! powerful image! im adding this one to my favourites</td>', 'i would give you an 11 if i could! powerful image! im adding this one to my favourites', '2004-11-15 01:07:53.000000', NULL, 1),
(1011159, 120697, 20210, '<td valign="top">oof, the title is going to hurt you.  It''s a bass, rather than a guitar (technically a "bass guitar", but people don''t really call it that).  Otherwise, a pretty solid photo, very impressionistic, like another current challenge.  I might have cropped a little tighter on the right, to let the line of the bass neck run corner-to-corner</td>', 'oof, the title is going to hurt you.  It''s a bass, rather than a guitar (technically a "bass guitar", but people don''t really call it that).  Otherwise, a pretty solid photo, very impressionistic, like another current challenge.  I might have cropped a little tighter on the right, to let the line of the bass neck run corner-to-corner', '2004-11-15 01:31:28.000000', NULL, 1),
(1011166, 121342, 18799, '<td valign="top">I don''t think this was the intent of the challenge.  That aside, the background is very distracting.</td>', 'I don''t think this was the intent of the challenge.  That aside, the background is very distracting.', '2004-11-15 01:40:52.000000', NULL, 1),
(1011177, 120676, 18799, '<td valign="top">Good pic.  More effective without the desat, IMO</td>', 'Good pic.  More effective without the desat, IMO', '2004-11-15 01:50:09.000000', NULL, 1),
(1011179, 121217, 18799, '<td valign="top">Good thought.  Unfortunately, the flash overpowers the image making it look snapshotish.</td>', 'Good thought.  Unfortunately, the flash overpowers the image making it look snapshotish.', '2004-11-15 01:52:06.000000', NULL, 1),
(1011183, 121342, 28108, '<td valign="top">Nice capture of personnality, that dog looks smarter than a lot of people I know! The background could have been more interesting alltough this is allright. I find there''s too much light reflection (probably from a window) in its eyes but I love the semi-profile. Nice! Real nice!</td>', 'Nice capture of personnality, that dog looks smarter than a lot of people I know! The background could have been more interesting alltough this is allright. I find there''s too much light reflection (probably from a window) in its eyes but I love the semi-profile. Nice! Real nice!', '2004-11-15 01:56:18.000000', NULL, 1),
(1011185, 120962, 18799, '<td valign="top">The message is clear.  The desat detracts however.</td>', 'The message is clear.  The desat detracts however.', '2004-11-15 01:57:12.000000', NULL, 1),
(1011206, 121270, 22245, '<td valign="top">White balance seems to be off .</td>', 'White balance seems to be off .', '2004-11-15 02:51:09.000000', NULL, 1),
(1011207, 121210, 22245, '<td valign="top">Great use of dsat.</td>', 'Great use of dsat.', '2004-11-15 02:51:48.000000', NULL, 1),
(1011208, 121334, 1368, '<td valign="top">Hell yeah. Now we are talking! This picture is sooo cool!  My only 10 in this challenge. Congrats on the blue ribbon! :)</td>', 'Hell yeah. Now we are talking! This picture is sooo cool!  My only 10 in this challenge. Congrats on the blue ribbon! :)', '2004-11-15 02:53:21.000000', NULL, 1),
(1011210, 120575, 22245, '<td valign="top">I have got this one marked for a ribbon.</td>', 'I have got this one marked for a ribbon.', '2004-11-15 02:55:05.000000', NULL, 1),
(1011214, 120709, 22245, '<td valign="top">Lovely portrait.</td>', 'Lovely portrait.', '2004-11-15 03:00:42.000000', NULL, 1),
(1011215, 120626, 22245, '<td valign="top">Think the dsat itakesw away from the over all image</td>', 'Think the dsat itakesw away from the over all image', '2004-11-15 03:01:56.000000', NULL, 1),
(1011216, 121358, 22479, '<td valign="top">Far too much dead space on the right, otherwise a moody and unique shot.</td>', 'Far too much dead space on the right, otherwise a moody and unique shot.', '2004-11-15 03:06:00.000000', NULL, 1),
(1011223, 121210, 24459, '<td valign="top">A nice pic. Not maybe the most heroic in the challenge but definitely has a nice feeling.</td>', 'A nice pic. Not maybe the most heroic in the challenge but definitely has a nice feeling.', '2004-11-15 03:28:57.000000', NULL, 1),
(1011225, 121037, 24459, '<td valign="top">OK: There''s a flag, there''s a soldier. All nice and cheesy, but presentation not very spectacullar. The pike with the flag seems to grow from the guy''s head and the overall feeling doesn''t touch me.</td>', 'OK: There''s a flag, there''s a soldier. All nice and cheesy, but presentation not very spectacullar. The pike with the flag seems to grow from the guy''s head and the overall feeling doesn''t touch me.', '2004-11-15 03:30:44.000000', NULL, 1),
(1011227, 121252, 24459, '<td valign="top">Nice pic. The DOF could be a little deeper imho, but this one also works ok.</td>', 'Nice pic. The DOF could be a little deeper imho, but this one also works ok.', '2004-11-15 03:33:05.000000', NULL, 1),
(1011229, 121050, 24459, '<td valign="top">Don''t find this pic very heroic, although it is a nice picture.</td>', 'Don''t find this pic very heroic, although it is a nice picture.', '2004-11-15 03:33:50.000000', NULL, 1),
(1011231, 121358, 6630, '<td valign="top">I think there is too much negatvie space in this picture.  Maybe a different crop would have worked better.  Just my opinion.</td>', 'I think there is too much negatvie space in this picture.  Maybe a different crop would have worked better.  Just my opinion.', '2004-11-15 03:37:12.000000', NULL, 1),
(1011232, 121344, 24459, '<td valign="top">An appropriate picture. Follows the challenge, composition is ok.</td>', 'An appropriate picture. Follows the challenge, composition is ok.', '2004-11-15 03:37:27.000000', NULL, 1),
(1011234, 121105, 24459, '<td valign="top">I''d love to see a bit more of the man''s face. But like the pic a lot anyway :)</td>', 'I''d love to see a bit more of the man''s face. But like the pic a lot anyway :)', '2004-11-15 03:38:40.000000', NULL, 1),
(1011235, 121217, 24459, '<td valign="top">Can''t loose the ''snapshot feeling''. Lack the expression I guess</td>', 'Can''t loose the ''snapshot feeling''. Lack the expression I guess', '2004-11-15 03:40:41.000000', NULL, 1),
(1011236, 120698, 24459, '<td valign="top">Nice lighting. Well done. I like the pround expression on his face.</td>', 'Nice lighting. Well done. I like the pround expression on his face.', '2004-11-15 03:41:16.000000', NULL, 1),
(1011237, 121181, 24459, '<td valign="top">Can''t see anything heroic about this shot, nor a like it in general.<br/>Nice contrasts though.</td>', 'Can''t see anything heroic about this shot, nor a like it in general.Nice contrasts though.', '2004-11-15 03:42:00.000000', NULL, 1),
(1011238, 120726, 24459, '<td valign="top">Just a snapshot and not a good one either. The two guys next to the military man don''t look like any heros at all. Flags not clear and showing them you also showed too much of the background wall.</td>', 'Just a snapshot and not a good one either. The two guys next to the military man don''t look like any heros at all. Flags not clear and showing them you also showed too much of the background wall.', '2004-11-15 03:43:56.000000', NULL, 1),
(1011240, 121215, 24459, '<td valign="top">That''s what you call a ''crowdy picture'' :)</td>', 'That''s what you call a ''crowdy picture'' :)', '2004-11-15 03:44:28.000000', NULL, 1),
(1011241, 121243, 24459, '<td valign="top">Touchy. And I like the obelisk in the background.</td>', 'Touchy. And I like the obelisk in the background.', '2004-11-15 03:45:14.000000', NULL, 1),
(1011242, 121402, 24459, '<td valign="top">I''m not sure about the ''rotation'' effect, but generally I really like the pic.</td>', 'I''m not sure about the ''rotation'' effect, but generally I really like the pic.', '2004-11-15 03:46:21.000000', NULL, 1),
(1011243, 120761, 24459, '<td valign="top">Having the face desaturated feels like the medals are more important that the man himself. Apart from that - a nice portrait</td>', 'Having the face desaturated feels like the medals are more important that the man himself. Apart from that - a nice portrait', '2004-11-15 03:47:24.000000', NULL, 1),
(1011244, 120608, 24459, '<td valign="top">I promise to come back and read the story. <br/>I guess when I know it I will understand it better.<br/>Until then it''s not my favourite. Then again it is an ''alternate idea'' which I tend to promote therefore a 6</td>', 'I promise to come back and read the story. I guess when I know it I will understand it better.Until then it''s not my favourite. Then again it is an ''alternate idea'' which I tend to promote therefore a 6', '2004-11-15 03:49:15.000000', NULL, 1),
(1011245, 121218, 24459, '<td valign="top">I bet they do, but without the title would anyone guess it''s about heroes?<br/>No chance</td>', 'I bet they do, but without the title would anyone guess it''s about heroes?No chance', '2004-11-15 03:49:55.000000', NULL, 1),
(1011246, 121336, 6130, '<td valign="top">Great 10</td>', 'Great 10', '2004-11-15 03:50:46.000000', NULL, 1),
(1011247, 121065, 24459, '<td valign="top">I tend to promote alternatives here but this crossed the border for me :)<br/></td>', 'I tend to promote alternatives here but this crossed the border for me :)', '2004-11-15 03:51:03.000000', NULL, 1),
(1011248, 120707, 24459, '<td valign="top">I like the idea, but I don''t like the picture at all. Can''t even tell who that is.</td>', 'I like the idea, but I don''t like the picture at all. Can''t even tell who that is.', '2004-11-15 03:52:07.000000', NULL, 1),
(1011250, 121424, 24459, '<td valign="top">I am a believer, but see NOTHING heroic about this picture whatsoever</td>', 'I am a believer, but see NOTHING heroic about this picture whatsoever', '2004-11-15 03:53:15.000000', NULL, 1),
(1011253, 121385, 24459, '<td valign="top">I like the idea, although the filters used are too strong. Also, I''d like to see the wheelchair - would make the pic ''fuller''.</td>', 'I like the idea, although the filters used are too strong. Also, I''d like to see the wheelchair - would make the pic ''fuller''.', '2004-11-15 03:56:14.000000', NULL, 1),
(1011258, 120907, 24459, '<td valign="top">Not the pose I guess. Would like to see the head too. Instead I have an impression of a tree growing on the guy''s shoulder.</td>', 'Not the pose I guess. Would like to see the head too. Instead I have an impression of a tree growing on the guy''s shoulder.', '2004-11-15 03:59:08.000000', NULL, 1),
(1011268, 120761, 23478, '<td valign="top">I really like this, the selective desat is good. 9.</td>', 'I really like this, the selective desat is good. 9.', '2004-11-15 04:12:53.000000', NULL, 1),
(1011273, 121349, 23478, '<td valign="top">Great photo, you have captured the essence of heroism at it''s finest.  This image cover 200 years of national history and heroism.  10.</td>', 'Great photo, you have captured the essence of heroism at it''s finest.  This image cover 200 years of national history and heroism.  10.', '2004-11-15 04:19:13.000000', NULL, 1),
(1011280, 121276, 23478, '<td valign="top">This is one of the best photos in this challenege.  The face tells it all and the lighting is excellent. 10.</td>', 'This is one of the best photos in this challenege.  The face tells it all and the lighting is excellent. 10.', '2004-11-15 04:24:18.000000', NULL, 1),
(1011291, 119712, 23478, '<td valign="top">Interesting take.</td>', 'Interesting take.', '2004-11-15 04:31:58.000000', NULL, 1),
(1011296, 121105, 23478, '<td valign="top">Great shot, it would be nice if he could have looked more towards the camera.</td>', 'Great shot, it would be nice if he could have looked more towards the camera.', '2004-11-15 04:35:37.000000', NULL, 1),
(1011298, 120962, 23478, '<td valign="top">It may have been stronger to select a different color to leave in, like the girls hair or shift it all to B&amp;W.  7.</td>', 'It may have been stronger to select a different color to leave in, like the girls hair or shift it all to B&W.  7.', '2004-11-15 04:37:18.000000', NULL, 1),
(1011302, 120576, 23478, '<td valign="top">Excellent photo.  8.</td>', 'Excellent photo.  8.', '2004-11-15 04:41:56.000000', NULL, 1),
(1011308, 121200, 23478, '<td valign="top">The color contrast makes this an excellent photo. 8.</td>', 'The color contrast makes this an excellent photo. 8.', '2004-11-15 04:49:14.000000', NULL, 1),
(1011310, 121050, 23478, '<td valign="top">Cool photo, I am not sure how well it fits in with the theme of heroes.  I can see it in a more abstract sense.  9.</td>', 'Cool photo, I am not sure how well it fits in with the theme of heroes.  I can see it in a more abstract sense.  9.', '2004-11-15 04:51:48.000000', NULL, 1),
(1011312, 121050, 27482, '<td valign="top">Awesome shot!!!  How on earth did you persuade that man to stand there???  Anyway, don´t know if you will win since I don´t consider this "heroic" but more "suicidal" but the shot itself just blows me away.  10</td>', 'Awesome shot!!!  How on earth did you persuade that man to stand there???  Anyway, don´t know if you will win since I don´t consider this "heroic" but more "suicidal" but the shot itself just blows me away.  10', '2004-11-15 05:02:49.000000', NULL, 1),
(1011313, 120907, 27482, '<td valign="top">Looks interesting enough but the composition is not good IMO, you cut off his feet and the tip of the sword and you can´t make out a face and you get no sense of what the hell he is doing and the backround doesn´t seem to go with the armour but this could have been a killer shot, keep it up.</td>', 'Looks interesting enough but the composition is not good IMO, you cut off his feet and the tip of the sword and you can´t make out a face and you get no sense of what the hell he is doing and the backround doesn´t seem to go with the armour but this could have been a killer shot, keep it up.', '2004-11-15 05:07:31.000000', NULL, 1),
(1011320, 120997, 29344, '<td valign="top">Great photo and imaginative, to me it say hero and steers away from the old war veteran miltary use of the word hero. There are many more heros in the world without guns.</td>', 'Great photo and imaginative, to me it say hero and steers away from the old war veteran miltary use of the word hero. There are many more heros in the world without guns.', '2004-11-15 05:39:28.000000', NULL, 1),
(1011327, 120997, 24459, '<td valign="top">My personal winner.<br/>Seeing my votes (i think our pics are similar in a way) I don''t expect this one to go up high (although I would love it to) or maybe I was just overexcited with my pic. Anyway, great job and good luck.</td>', 'My personal winner.Seeing my votes (i think our pics are similar in a way) I don''t expect this one to go up high (although I would love it to) or maybe I was just overexcited with my pic. Anyway, great job and good luck.', '2004-11-15 05:55:12.000000', NULL, 1),
(1011329, 121334, 24459, '<td valign="top">Very creative and very DIFFERENT from all the obvious ones. Great job.</td>', 'Very creative and very DIFFERENT from all the obvious ones. Great job.', '2004-11-15 05:56:21.000000', NULL, 1),
(1011331, 121336, 24459, '<td valign="top">The guy is rather scarry, but I must score it high for the quality. I see some similarity with the one DVD cover (wasn''t that Mozart too?) but still like it very much.</td>', 'The guy is rather scarry, but I must score it high for the quality. I see some similarity with the one DVD cover (wasn''t that Mozart too?) but still like it very much.', '2004-11-15 05:58:20.000000', NULL, 1),
(1011344, 120761, 27482, '<td valign="top">I don´t think the selective desat is working at all in this image.  As a portrait this isn´t horrible at all, but hardly good either, just about average and then the medals draw enough attention as it is without the colours so I just can´t give it anything but a 5.</td>', 'I don´t think the selective desat is working at all in this image.  As a portrait this isn´t horrible at all, but hardly good either, just about average and then the medals draw enough attention as it is without the colours so I just can´t give it anything but a 5.', '2004-11-15 06:16:17.000000', NULL, 1),
(1011347, 121121, 27482, '<td valign="top">Good control over DOF, it´s spot on how I would do it.  Good image, hope you do well.</td>', 'Good control over DOF, it´s spot on how I would do it.  Good image, hope you do well.', '2004-11-15 06:26:18.000000', NULL, 1),
(1011392, 121200, 26930, '<td valign="top">Powerfull, I realy like it</td>', 'Powerfull, I realy like it', '2004-11-15 07:23:51.000000', NULL, 1),
(1011422, 121101, 27482, '<td valign="top">Very cool shot, I love the composition.</td>', 'Very cool shot, I love the composition.', '2004-11-15 07:55:21.000000', NULL, 1),
(1011427, 120641, 25150, '<td valign="top">FYI - Harry Lampert, the illustrator who created the DC Comics superhero "The Flash" died on Saturday 11/13/04. He was 88.<br/></td>', 'FYI - Harry Lampert, the illustrator who created the DC Comics superhero "The Flash" died on Saturday 11/13/04. He was 88.', '2004-11-15 07:57:26.000000', NULL, 1),
(1011428, 121336, 19952, '<td valign="top">Wow - that''s a heck of a reproduction. Nice job with the setup and the lighting.</td>', 'Wow - that''s a heck of a reproduction. Nice job with the setup and the lighting.', '2004-11-15 07:57:54.000000', NULL, 1),
(1011432, 121279, 27161, '<td valign="top">Really great setup.  Wish there was a little more light.</td>', 'Really great setup.  Wish there was a little more light.', '2004-11-15 07:58:53.000000', NULL, 1),
(1011438, 121402, 19952, '<td valign="top">This is a really excellent image for this challenge. I think it would benefit from a bit more contrast and maybe a tad less noise around the face, but other than that, this is a really nice shot.</td>', 'This is a really excellent image for this challenge. I think it would benefit from a bit more contrast and maybe a tad less noise around the face, but other than that, this is a really nice shot.', '2004-11-15 08:02:41.000000', NULL, 1),
(1011445, 121331, 19952, '<td valign="top">This is an excellent example of how an outdoor portrait should be done. The colors, composition and DOF are outstanding. Really great job.</td>', 'This is an excellent example of how an outdoor portrait should be done. The colors, composition and DOF are outstanding. Really great job.', '2004-11-15 08:05:11.000000', NULL, 1),
(1011455, 120641, 19952, '<td valign="top">This is a really fun and well done shot. You might want to clone out the wires and that white spot in the bottom right corner, but other than that, this is an excellent photo for this challenge. Nice job.</td>', 'This is a really fun and well done shot. You might want to clone out the wires and that white spot in the bottom right corner, but other than that, this is an excellent photo for this challenge. Nice job.', '2004-11-15 08:09:32.000000', NULL, 1),
(1011466, 120608, 19952, '<td valign="top">You tease! ;-) My only feedback would be to remove that magazine he''s holding and to go for a simpler, flat background. You might also want to get lower for this shot to go for a more dynamic angle. Other than that, this is a very nice shot for this challenge.</td>', 'You tease! ;-) My only feedback would be to remove that magazine he''s holding and to go for a simpler, flat background. You might also want to get lower for this shot to go for a more dynamic angle. Other than that, this is a very nice shot for this challenge.', '2004-11-15 08:16:58.000000', NULL, 1),
(1011473, 121156, 19952, '<td valign="top">Too funny! :-) And this is a nice simple shot with excellent composition. Nice job!</td>', 'Too funny! :-) And this is a nice simple shot with excellent composition. Nice job!', '2004-11-15 08:22:46.000000', NULL, 1),
(1011475, 120030, 19952, '<td valign="top">This is a nice, simple shot of an excellent subject. My only feedback is that the colors look a bit oversaturated. Otherwise, very nice job.</td>', 'This is a nice, simple shot of an excellent subject. My only feedback is that the colors look a bit oversaturated. Otherwise, very nice job.', '2004-11-15 08:24:02.000000', NULL, 1),
(1011494, 120954, 19952, '<td valign="top">I really like the composition of this shot, but that adoring look from your daughter might show her face better if she were standing behind you looking slightly down. Also, a little more light from stage left might offset her shadow a bit. Otherwise, really nice shot and an excellent photo for this challenge.</td>', 'I really like the composition of this shot, but that adoring look from your daughter might show her face better if she were standing behind you looking slightly down. Also, a little more light from stage left might offset her shadow a bit. Otherwise, really nice shot and an excellent photo for this challenge.', '2004-11-15 08:47:27.000000', NULL, 1),
(1011513, 121121, 6008, '<td valign="top">I find my personal interpretation of this image interesting and am curious to see if that was the intended message or not. The drink has bad connotations for me as in s/he has been driven to alchol as a result of the job, but the cigar has a celebratory feel or one of relaxation. There is a clear duality present in the image. Photographically it looks good, but the placement of the cigar looks a little odd.</td>', 'I find my personal interpretation of this image interesting and am curious to see if that was the intended message or not. The drink has bad connotations for me as in s/he has been driven to alchol as a result of the job, but the cigar has a celebratory feel or one of relaxation. There is a clear duality present in the image. Photographically it looks good, but the placement of the cigar looks a little odd.', '2004-11-15 08:56:30.000000', NULL, 1),
(1011537, 121416, 20577, '<td valign="top">This is the winner. Very moving capture.</td>', 'This is the winner. Very moving capture.', '2004-11-15 09:12:51.000000', NULL, 1),
