(1022713, 120676, 27839, '<td valign="top">Very nice touch with the red button.</td>', 'Very nice touch with the red button.', '2004-11-19 18:25:27.000000', NULL, 1),
(1022722, 121402, 27839, '<td valign="top">Very nice.  This looks like it was a candid photo.  I like that her head is tilted down, it shows a lot of emotion.</td>', 'Very nice.  This looks like it was a candid photo.  I like that her head is tilted down, it shows a lot of emotion.', '2004-11-19 18:28:18.000000', NULL, 1),
(1022728, 121101, 27839, '<td valign="top">I like the angle, but I can''t make out what statue this is.</td>', 'I like the angle, but I can''t make out what statue this is.', '2004-11-19 18:29:45.000000', NULL, 1),
(1022764, 120641, 27842, '<td valign="top">Nice blur effect and interesting choice of subject.</td>', 'Nice blur effect and interesting choice of subject.', '2004-11-19 18:40:49.000000', NULL, 1),
(1022770, 121385, 27842, '<td valign="top">Nice isolation of the subject.  Front of tray and right finger tips out of focus.  More DOF/smaller aperture would have helped this.</td>', 'Nice isolation of the subject.  Front of tray and right finger tips out of focus.  More DOF/smaller aperture would have helped this.', '2004-11-19 18:42:43.000000', NULL, 1),
(1022802, 121402, 27842, '<td valign="top">Very nice capture.  Good emotion, great composition and visual interest.  My only slight criticism is that the face seems a little gray as if it could use a little more saturation. 8</td>', 'Very nice capture.  Good emotion, great composition and visual interest.  My only slight criticism is that the face seems a little gray as if it could use a little more saturation. 8', '2004-11-19 18:53:16.000000', NULL, 1),
(1022807, 121241, 27842, '<td valign="top">A lower angle might have captured more of the cross.  Nice otherwise.</td>', 'A lower angle might have captured more of the cross.  Nice otherwise.', '2004-11-19 18:54:31.000000', NULL, 1),
(1022812, 120997, 27842, '<td valign="top">Nice creative shot,  There is a distracting fringe around the top of the bottle and the bottom of the cape.</td>', 'Nice creative shot,  There is a distracting fringe around the top of the bottle and the bottom of the cape.', '2004-11-19 18:56:04.000000', NULL, 1),
(1022821, 121349, 29228, '<td valign="top">Thats very deep. conveys a lot of emotion. great shot. :] all though, i dont know what that dark shadow is in the bottom left corner, but it takes away from the shot. 7.</td>', 'Thats very deep. conveys a lot of emotion. great shot. :] all though, i dont know what that dark shadow is in the bottom left corner, but it takes away from the shot. 7.', '2004-11-19 19:00:10.000000', NULL, 1),
(1022849, 120698, 27842, '<td valign="top">Strong shadows work well in this photo.  Nice post processing of background.</td>', 'Strong shadows work well in this photo.  Nice post processing of background.', '2004-11-19 19:09:03.000000', NULL, 1),
(1022853, 121331, 27842, '<td valign="top">Great color and composition.  I think the white balance may be off slightly -- the shoes have a blue cast.</td>', 'Great color and composition.  I think the white balance may be off slightly -- the shoes have a blue cast.', '2004-11-19 19:10:59.000000', NULL, 1),
(1023310, 121243, 29009, '<td valign="top">Excellent composition - I really like how you used DOF and set up the monument to be in line with the rose.  Facial expression captured perfectly.  Great shot!</td>', 'Excellent composition - I really like how you used DOF and set up the monument to be in line with the rose.  Facial expression captured perfectly.  Great shot!', '2004-11-19 22:57:50.000000', NULL, 1),
(1023311, 120698, 29009, '<td valign="top">Very moving image - you''ve captured both seriousness of duty and sense of pride in the expression.  Good use of DOF to really make the focal point pop.  One of my faves in this challenge!</td>', 'Very moving image - you''ve captured both seriousness of duty and sense of pride in the expression.  Good use of DOF to really make the focal point pop.  One of my faves in this challenge!', '2004-11-19 22:58:53.000000', NULL, 1),
(1023313, 121276, 29009, '<td valign="top">Black and white was a great choice for this subject - great capture of facial expression.  Excellent shot!</td>', 'Black and white was a great choice for this subject - great capture of facial expression.  Excellent shot!', '2004-11-19 23:00:07.000000', NULL, 1),
(1023318, 121006, 29009, '<td valign="top">Quite a striking shot - good capture of facial expression and use of lighting so their is no obvious shadow from the brim of the hat.</td>', 'Quite a striking shot - good capture of facial expression and use of lighting so their is no obvious shadow from the brim of the hat.', '2004-11-19 23:02:26.000000', NULL, 1),
(1023324, 121416, 29009, '<td valign="top">Very moving shot.  I love the composition - the reflection of the hands on the wall adds so much.  An emotional entry, very powerful.  One of my favorites in the challenge!</td>', 'Very moving shot.  I love the composition - the reflection of the hands on the wall adds so much.  An emotional entry, very powerful.  One of my favorites in the challenge!', '2004-11-19 23:03:46.000000', NULL, 1),
(1023328, 121105, 29009, '<td valign="top">This was a very moving shot - excellent composition and great capture of the private moment.  Aptly titled...a truly "wow" image.</td>', 'This was a very moving shot - excellent composition and great capture of the private moment.  Aptly titled...a truly "wow" image.', '2004-11-19 23:05:20.000000', NULL, 1),
(1023335, 119712, 29009, '<td valign="top">While I can''t say I agree with your choice of a "hero" this shot made me laugh so hard I''m giving it a (9).  Excellent composition - both well planned and executed.  The location of the magazines in the bathroom was the final winning touch!</td>', 'While I can''t say I agree with your choice of a "hero" this shot made me laugh so hard I''m giving it a (9).  Excellent composition - both well planned and executed.  The location of the magazines in the bathroom was the final winning touch!', '2004-11-19 23:07:13.000000', NULL, 1),
(1023337, 120634, 29009, '<td valign="top">Excellent use of selective desat here.  Very moving image...well composed.</td>', 'Excellent use of selective desat here.  Very moving image...well composed.', '2004-11-19 23:08:05.000000', NULL, 1),
(1023343, 121337, 29009, '<td valign="top">I absolutely love the way you used selective saturation here - so subtle and yet so effective.  You''ve captured an emotional moment very well - you must be very pleased with this shot.  One of my favorite entries in the challenge.</td>', 'I absolutely love the way you used selective saturation here - so subtle and yet so effective.  You''ve captured an emotional moment very well - you must be very pleased with this shot.  One of my favorite entries in the challenge.', '2004-11-19 23:09:56.000000', NULL, 1),
(1023355, 120962, 2798, '<td valign="top">What purpose does the selective desaturation serve here? 6</td>', 'What purpose does the selective desaturation serve here? 6', '2004-11-19 23:13:15.000000', NULL, 1),
(1023356, 121358, 2798, '<td valign="top">Very confident use of negative space - me likey. 9</td>', 'Very confident use of negative space - me likey. 9', '2004-11-19 23:14:23.000000', NULL, 1),
(1023359, 120899, 29009, '<td valign="top">I really love this entry - black and white was a good choice here.  I find myself returning to it again and again.  At first I was not sure about the motion blur in the lower right hand corner, but have come to the conclusion that it works because it seems to reinforce the theme.  In any event, the shot really made me stop and think (and appreciate) the sacrifices made by servicemen to serve their country.  Great job!</td>', 'I really love this entry - black and white was a good choice here.  I find myself returning to it again and again.  At first I was not sure about the motion blur in the lower right hand corner, but have come to the conclusion that it works because it seems to reinforce the theme.  In any event, the shot really made me stop and think (and appreciate) the sacrifices made by servicemen to serve their country.  Great job!', '2004-11-19 23:15:25.000000', NULL, 1),
(1023365, 121361, 2798, '<td valign="top">Im knocking points off every photo I see that uses selective desaturation without a clear and valid purpose. In this case your desaturation of everything except red has helped keep the focus on your subject but this alone is not reason enough to use a technique that has become somewhat hackneyed on DPC. Drawing the viewer''s eye to your subject is something you should be doing in your composition not your post processing. 6</td>', 'Im knocking points off every photo I see that uses selective desaturation without a clear and valid purpose. In this case your desaturation of everything except red has helped keep the focus on your subject but this alone is not reason enough to use a technique that has become somewhat hackneyed on DPC. Drawing the viewer''s eye to your subject is something you should be doing in your composition not your post processing. 6', '2004-11-19 23:18:03.000000', NULL, 1),
(1023367, 121210, 2798, '<td valign="top">Gah yet another picture using selective desaturation. In this case there is at least a reason albeit a touch hackneyed. 7</td>', 'Gah yet another picture using selective desaturation. In this case there is at least a reason albeit a touch hackneyed. 7', '2004-11-19 23:19:04.000000', NULL, 1),
(1023371, 121416, 2798, '<td valign="top">Not an original idea in this challenge but certainly one of the best executed of this style. Emotive, recognisable and simple. Well done. 10.</td>', 'Not an original idea in this challenge but certainly one of the best executed of this style. Emotive, recognisable and simple. Well done. 10.', '2004-11-19 23:20:38.000000', NULL, 1),
(1023373, 121418, 29009, '<td valign="top">You''ve captured the facial expression well.  I''m not so sure about the overexposure.  It appears intentional, but leaves the viewer with a sense of a "floating head."</td>', 'You''ve captured the facial expression well.  I''m not so sure about the overexposure.  It appears intentional, but leaves the viewer with a sense of a "floating head."', '2004-11-19 23:21:50.000000', NULL, 1),
(1023374, 121270, 2798, '<td valign="top">I find myself wondering what''s inside that casserole type dish on your coffee table.</td>', 'I find myself wondering what''s inside that casserole type dish on your coffee table.', '2004-11-19 23:21:50.000000', NULL, 1),
(1023377, 121105, 2798, '<td valign="top">A lovely candid that captures the moment well. A little tightly cropped I think but otherwise perfect. 9</td>', 'A lovely candid that captures the moment well. A little tightly cropped I think but otherwise perfect. 9', '2004-11-19 23:22:45.000000', NULL, 1),
(1023381, 120710, 2798, '<td valign="top">A very nicely taken portrait shoe horned into the challenge topic. ;-) 8</td>', 'A very nicely taken portrait shoe horned into the challenge topic. ;-) 8', '2004-11-19 23:24:34.000000', NULL, 1),
(1023386, 121101, 2798, '<td valign="top">If I cant tell who this is then the picture loses all its meaning. It''s a good dramatic angle but you''ve forgotten that your viewer doesnt know what you do. 7</td>', 'If I cant tell who this is then the picture loses all its meaning. It''s a good dramatic angle but you''ve forgotten that your viewer doesnt know what you do. 7', '2004-11-19 23:26:17.000000', NULL, 1),
(1023392, 121370, 29009, '<td valign="top">Thank you for your entry!  While this might not have been a popular conflict, there were many heroes that deserve recognition.  One thing you might consider next time is bouncing some light upwards to soften the shadow from the top of the monument.  Additionally, it might have been a stronger composition if the white background elements were level on each side.</td>', 'Thank you for your entry!  While this might not have been a popular conflict, there were many heroes that deserve recognition.  One thing you might consider next time is bouncing some light upwards to soften the shadow from the top of the monument.  Additionally, it might have been a stronger composition if the white background elements were level on each side.', '2004-11-19 23:27:44.000000', NULL, 1),
(1023396, 119712, 2798, '<td valign="top">Very edgy indeed. I hope you don''t expect to score well but I admire your spunk, err guts. 8</td>', 'Very edgy indeed. I hope you don''t expect to score well but I admire your spunk, err guts. 8', '2004-11-19 23:29:07.000000', NULL, 1),
(1023399, 121101, 29009, '<td valign="top">You''ve got some creative composition here which adds lots of visual interest.</td>', 'You''ve got some creative composition here which adds lots of visual interest.', '2004-11-19 23:29:48.000000', NULL, 1),
(1023401, 121276, 2798, '<td valign="top">I don''t know who he is but he sure looks mighty heroic. Some clue would have been nice. Excellent portrait. 8</td>', 'I don''t know who he is but he sure looks mighty heroic. Some clue would have been nice. Excellent portrait. 8', '2004-11-19 23:29:55.000000', NULL, 1),
(1023410, 121208, 29009, '<td valign="top">Good composition (use of lines) here.</td>', 'Good composition (use of lines) here.', '2004-11-19 23:31:23.000000', NULL, 1),
(1023411, 120657, 2798, '<td valign="top">Im confused - is this lad supposed to be an unsung hero? Hero of what? More cluse please. 7</td>', 'Im confused - is this lad supposed to be an unsung hero? Hero of what? More cluse please. 7', '2004-11-19 23:31:30.000000', NULL, 1),
(1023418, 121334, 2798, '<td valign="top">It''s neat but what the heck is going on here?</td>', 'It''s neat but what the heck is going on here?', '2004-11-19 23:33:09.000000', NULL, 1),
(1023420, 121349, 29009, '<td valign="top">This is a really excellent shot - I love the way you''ve used the reflection of the monument to reinforce your theme.  I find I''m a little distracted by the dark reflection at the bottom, but overall this is a great shot and you have a lot to be pleased about.</td>', 'This is a really excellent shot - I love the way you''ve used the reflection of the monument to reinforce your theme.  I find I''m a little distracted by the dark reflection at the bottom, but overall this is a great shot and you have a lot to be pleased about.', '2004-11-19 23:33:29.000000', NULL, 1),
(1023430, 120634, 2798, '<td valign="top">At last somenoe using selective desaturation with a clear valid purpose. Good emotive work with creat composition and meaning. 9 well done</td>', 'At last somenoe using selective desaturation with a clear valid purpose. Good emotive work with creat composition and meaning. 9 well done', '2004-11-19 23:35:40.000000', NULL, 1),
(1023435, 121252, 2798, '<td valign="top">The focus here is on the name John instead of the many names of the men and women who died. Unless this is meant to be an homage to a particular John Bell then I think a wider view and deeper DOF would have helped. 8</td>', 'The focus here is on the name John instead of the many names of the men and women who died. Unless this is meant to be an homage to a particular John Bell then I think a wider view and deeper DOF would have helped. 8', '2004-11-19 23:37:18.000000', NULL, 1),
(1023441, 120954, 2798, '<td valign="top">Wow - one that makes you think and captures an emotional point. Shame about the loss of the left guys hair in the dark background. That''s my only complaint though. 8</td>', 'Wow - one that makes you think and captures an emotional point. Shame about the loss of the left guys hair in the dark background. That''s my only complaint though. 8', '2004-11-19 23:39:30.000000', NULL, 1),
(1023445, 120676, 2798, '<td valign="top">Yet more selective desaturation with naught but the most threadbare purpose. Surely the focus of this image should be on the people - not the button? 6</td>', 'Yet more selective desaturation with naught but the most threadbare purpose. Surely the focus of this image should be on the people - not the button? 6', '2004-11-19 23:40:50.000000', NULL, 1),
(1023448, 121102, 2798, '<td valign="top">Nope - no clue what this is all about. 6</td>', 'Nope - no clue what this is all about. 6', '2004-11-19 23:42:28.000000', NULL, 1),
(1023451, 120894, 2798, '<td valign="top">Yet more selective desaturation with naught but the most threadbare purpose. 6</td>', 'Yet more selective desaturation with naught but the most threadbare purpose. 6', '2004-11-19 23:43:18.000000', NULL, 1),
(1023453, 121121, 29009, '<td valign="top">Strong composition, well planned and executed.  I''m not sure about including the drink as an element for this particular challenge, but that''s just me.  Overall, I really liked this shot.</td>', 'Strong composition, well planned and executed.  I''m not sure about including the drink as an element for this particular challenge, but that''s just me.  Overall, I really liked this shot.', '2004-11-19 23:43:38.000000', NULL, 1),
(1023456, 120761, 2798, '<td valign="top">I don''t doubt his heroism but with that smile Im not sure I''d buy a used car from him. 8</td>', 'I don''t doubt his heroism but with that smile Im not sure I''d buy a used car from him. 8', '2004-11-19 23:44:40.000000', NULL, 1),
(1023460, 121030, 2798, '<td valign="top">Good idea - one of the few unique ideas in this challenge. 8</td>', 'Good idea - one of the few unique ideas in this challenge. 8', '2004-11-19 23:45:28.000000', NULL, 1),
(1023462, 121279, 2798, '<td valign="top">Aziz! Light! (needs more)</td>', 'Aziz! Light! (needs more)', '2004-11-19 23:46:24.000000', NULL, 1),
(1023463, 120707, 29009, '<td valign="top">You''ve got some great colors here.  I think it would have been a stronger image overall if you had been able to get a little closer and see some faces.</td>', 'You''ve got some great colors here.  I think it would have been a stronger image overall if you had been able to get a little closer and see some faces.', '2004-11-19 23:46:40.000000', NULL, 1),
(1023470, 120626, 2798, '<td valign="top">Probably the best example yet of selective desaturation without a valid purpose. Your use of it here has actually managed to draw the eye AWAY from what I assume was meant to be the focus of this picture. If the wheel-thing was supposed to be the focus then we really need to be able to see better what it is. 5</td>', 'Probably the best example yet of selective desaturation without a valid purpose. Your use of it here has actually managed to draw the eye AWAY from what I assume was meant to be the focus of this picture. If the wheel-thing was supposed to be the focus then we really need to be able to see better what it is. 5', '2004-11-19 23:49:22.000000', NULL, 1),
(1023471, 121358, 29009, '<td valign="top">I can tell you had a great idea.  The composition is off to a good start, but there is so much negative space I''m not sure it works as well as you might have intended.  The girl herself seems a bit blurry.  I find I''m wishing for a closer view.</td>', 'I can tell you had a great idea.  The composition is off to a good start, but there is so much negative space I''m not sure it works as well as you might have intended.  The girl herself seems a bit blurry.  I find I''m wishing for a closer view.', '2004-11-19 23:49:24.000000', NULL, 1),
(1023491, 120656, 29009, '<td valign="top">You''ve captured the building very well.  While I can appreciate your desire to honor the athletes, this particular shot doesn''t work as well overall as you might have wished.  Perhaps choosing an element of the building as a focal point (like the part with the rings on it) might have conveyed your intent more clearly.  Without the title, this shot couldn''t stand for a "hero" on it''s own.</td>', 'You''ve captured the building very well.  While I can appreciate your desire to honor the athletes, this particular shot doesn''t work as well overall as you might have wished.  Perhaps choosing an element of the building as a focal point (like the part with the rings on it) might have conveyed your intent more clearly.  Without the title, this shot couldn''t stand for a "hero" on it''s own.', '2004-11-19 23:57:36.000000', NULL, 1),
(1023495, 121213, 29009, '<td valign="top">Sailors are our heroes - agreed!   You''ve done a good job capturing the movement of the waves and an excellent job with the color.  Without the title, I''m not sure this photo would obviously be of a hero.  Perhaps a composition including a closer view of the boat and some of the sailors on it would have conveyed your intent more clearly.  Overall, a good image and one I enjoyed.</td>', 'Sailors are our heroes - agreed!   You''ve done a good job capturing the movement of the waves and an excellent job with the color.  Without the title, I''m not sure this photo would obviously be of a hero.  Perhaps a composition including a closer view of the boat and some of the sailors on it would have conveyed your intent more clearly.  Overall, a good image and one I enjoyed.', '2004-11-20 00:01:31.000000', NULL, 1),
(1023510, 120899, 12253, '<td valign="top">Excellent shot--I like added effect of the the motion blur too.  Was this being shot for a movie (guessing from the black background and studio style lighting!)</td>', 'Excellent shot--I like added effect of the the motion blur too.  Was this being shot for a movie (guessing from the black background and studio style lighting!)', '2004-11-20 00:07:07.000000', NULL, 1),
(1023513, 121200, 12253, '<td valign="top">Very effective shot and looks carefully composed cropped for all the right elements.</td>', 'Very effective shot and looks carefully composed cropped for all the right elements.', '2004-11-20 00:08:45.000000', NULL, 1),
(1023517, 121349, 12253, '<td valign="top">While it''s neat to see the washington monument reflected here, to me it is only a distraction from the theme.  To me, the  heroes theme would call for a person to be reflected there, maybe in uniform, maybe a widow, etc.</td>', 'While it''s neat to see the washington monument reflected here, to me it is only a distraction from the theme.  To me, the  heroes theme would call for a person to be reflected there, maybe in uniform, maybe a widow, etc.', '2004-11-20 00:10:20.000000', NULL, 1),
(1023522, 121416, 12253, '<td valign="top">I like this and the use of the reflection.  However, to mee the other hands are distracting --it''s hard to tell how many are here.  And the hand isnt in sharp focus except in the reflection--more DOF is needed IMHO.</td>', 'I like this and the use of the reflection.  However, to mee the other hands are distracting --it''s hard to tell how many are here.  And the hand isnt in sharp focus except in the reflection--more DOF is needed IMHO.', '2004-11-20 00:11:47.000000', NULL, 1),
(1023524, 120894, 93, '<td valign="top">I like this.  The style this photograph is in works really well, composition is wonderful, and the look of the dog''s face is brilliant.</td>', 'I like this.  The style this photograph is in works really well, composition is wonderful, and the look of the dog''s face is brilliant.', '2004-11-20 00:13:06.000000', NULL, 1),
(1023527, 120575, 93, '<td valign="top">I like this.  Good composition (could have used less crop on the bottom), and I love the eye being centered.</td>', 'I like this.  Good composition (could have used less crop on the bottom), and I love the eye being centered.', '2004-11-20 00:13:49.000000', NULL, 1),
(1023601, 121276, 29486, '<td valign="top">Very nice!</td>', 'Very nice!', '2004-11-20 01:19:36.000000', NULL, 1),
(1023604, 121050, 29486, '<td valign="top">Very interesting photo but I felt it was a bit off topic. I know I wouldn''t want to be standing there either.</td>', 'Very interesting photo but I felt it was a bit off topic. I know I wouldn''t want to be standing there either.', '2004-11-20 01:23:56.000000', NULL, 1),
(1023605, 120761, 29486, '<td valign="top">Interesting technique</td>', 'Interesting technique', '2004-11-20 01:25:10.000000', NULL, 1),
(1023606, 120726, 29486, '<td valign="top">Too much dead space.  I would think the people are the focus, not the flags.</td>', 'Too much dead space.  I would think the people are the focus, not the flags.', '2004-11-20 01:26:17.000000', NULL, 1),
(1023608, 121297, 29486, '<td valign="top">Lacked contrast. Seemed hard to focus.</td>', 'Lacked contrast. Seemed hard to focus.', '2004-11-20 01:26:50.000000', NULL, 1),
(1023609, 120576, 29486, '<td valign="top">Good pic</td>', 'Good pic', '2004-11-20 01:27:31.000000', NULL, 1),
(1023610, 120658, 29486, '<td valign="top">Great lighting. The age of the hands give it a lot of character.</td>', 'Great lighting. The age of the hands give it a lot of character.', '2004-11-20 01:28:03.000000', NULL, 1),
(1023612, 121252, 29486, '<td valign="top">I like the concept but not enough contrast for my taste.</td>', 'I like the concept but not enough contrast for my taste.', '2004-11-20 01:29:33.000000', NULL, 1),
(1023613, 121331, 29486, '<td valign="top">Nice color</td>', 'Nice color', '2004-11-20 01:30:49.000000', NULL, 1),
(1023616, 121358, 29486, '<td valign="top">Too dark</td>', 'Too dark', '2004-11-20 01:34:45.000000', NULL, 1),
(1023617, 121121, 29486, '<td valign="top">I''m not sure the point of the drink. Great photo though</td>', 'I''m not sure the point of the drink. Great photo though', '2004-11-20 01:35:37.000000', NULL, 1),
(1023619, 120907, 29486, '<td valign="top">Pretty stunning overall BUT the lack of a head AND the fact that the tree is sticking out of the body knocks the rating down. I''m guessing it was hard enough just to get this shot and you got what you got. Good effort!</td>', 'Pretty stunning overall BUT the lack of a head AND the fact that the tree is sticking out of the body knocks the rating down. I''m guessing it was hard enough just to get this shot and you got what you got. Good effort!', '2004-11-20 01:37:17.000000', NULL, 1),
(1023621, 121336, 29486, '<td valign="top">Good lighting</td>', 'Good lighting', '2004-11-20 01:37:35.000000', NULL, 1),
(1023622, 121312, 29486, '<td valign="top">For me it''s an unflattering pose against a background that looks trashy. I don''t mind Punk Rock but maybe she could have been doing something else.</td>', 'For me it''s an unflattering pose against a background that looks trashy. I don''t mind Punk Rock but maybe she could have been doing something else.', '2004-11-20 01:39:37.000000', NULL, 1),
(1023624, 121068, 29486, '<td valign="top">Since you''re on a first name basis with the man, I would have liked to see him doing something in a better pose.</td>', 'Since you''re on a first name basis with the man, I would have liked to see him doing something in a better pose.', '2004-11-20 01:40:53.000000', NULL, 1),
(1023655, 121349, 23913, '<td valign="top">wonderful image it really speaks for the challenge.<br/> <br/>well taken great comp.</td>', 'wonderful image it really speaks for the challenge. well taken great comp.', '2004-11-20 02:14:41.000000', NULL, 1),
(1023661, 120575, 23913, '<td valign="top">No kiddin'' i had no idea.-LOL<br/> <br/>i like the lighting of this image it also is well framed(ie.not showing to much face below the mask just enough for the title and the image to work together)<br/> <br/>intrusting concept</td>', 'No kiddin'' i had no idea.-LOL i like the lighting of this image it also is well framed(ie.not showing to much face below the mask just enough for the title and the image to work together) intrusting concept', '2004-11-20 02:20:57.000000', NULL, 1);
