(1026561, 121416, 22734, '<td valign="top">Terry: my warmest congratulation on this well earned blue ribbon. you have certainly outdone yourself with this touching image.</td>', 'Terry: my warmest congratulation on this well earned blue ribbon. you have certainly outdone yourself with this touching image.', '2004-11-22 01:02:33.000000', NULL, 0),
